"""Debates (nona leva): uso do tempo para melhorar o mundo, doação para causas eficazes, compensação moral."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
CO = 'Cotidiano'

DEBATES9 = [
dict(s='uso-do-tempo', n='Como usar o tempo para melhorar o mundo?', t=CO, r='Oitenta mil horas de trabalho, mais o resto. Carreira, voluntariado, ativismo, cuidado: o que a ética diz sobre onde colocar o recurso que não se recupera.',
 v='Dinheiro se repõe; tempo, não. Uma vida adulta tem cerca de 80 mil horas de trabalho, e muitas outras fora dele. A pergunta de como usá-las para fazer bem é tão moral quanto a de como usar o dinheiro, e tem as mesmas armadilhas: a exigência infinita, o gesto simbólico e a desculpa de que nada faz diferença.',
 lados=[('O tempo como recurso moral', ['Carreira: a escolha de profissão é a maior decisão de impacto que a maioria faz; algumas carreiras fazem muito mais bem do que outras, e a diferença é mensurável (80,000 Hours).', 'Ganhar para doar: para alguns, o maior impacto vem de ganhar bem e doar muito; para outros, de trabalhar diretamente no problema.', 'Voluntariado e ativismo: horas dedicadas a causas com evidência de resultado fazem diferença; horas dedicadas a gestos que só aliviam a consciência, não.', 'Prioridades: o critério de importância, negligência e tratabilidade serve ao tempo como ao dinheiro.']),
        ('Os limites', ['Exigência: uma vida inteiramente otimizada para o impacto não é vivível; descanso, relações e prazer não são desperdício. Veja quanto a moral pode exigir.', 'Cuidado invisível: criar filhos, cuidar de pais, sustentar uma comunidade são usos do tempo que nenhuma planilha de impacto capta bem, e são parte do que uma vida boa exige.', 'Incerteza: o impacto de uma carreira é difícil de prever; apostar tudo em um cálculo frágil é imprudente.', 'O risco do cálculo: tratar as pessoas em volta como custos de oportunidade corrói o que as relações são.'])],
 c=['A pergunta tem uma versão sensata (“dado o que vou fazer da vida, onde o mesmo esforço faz mais bem?”) e uma versão tirânica (“cada hora deve maximizar”); a primeira é ética, a segunda não é vivível.', 'Para a maioria, a decisão mais importante é a carreira, e ela se toma poucas vezes; o resto são ajustes.', 'Tempo dado a causas eficazes e tempo dado aos próximos não competem tanto quanto parece: o segundo sustenta o primeiro.'],
 p=('parcial', 'O peso está com tratar o tempo como recurso moral: a carreira e as horas de dedicação importam, e algumas escolhas fazem muito mais bem do que outras, o que vale saber antes de decidir. Os limites são os mesmos da doação: a exigência infinita não funciona, o cuidado e as relações não são desperdício, e a conta é um guia, não um tirano. A posição mais defendida é decidir bem as poucas escolhas grandes e viver o resto sem culpa.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'O tempo vale pelo bem que produz; a carreira é a maior alavanca.'), ('etica-das-virtudes', 'Virtudes', 'Uma vida boa inclui trabalho com sentido, relações e descanso; otimizar tudo é um vício.'), ('etica-do-cuidado', 'Cuidado', 'O tempo dado a quem depende de você é o uso mais básico, e o menos contado.'), ('deontologia-kantiana', 'Kant', 'Dever imperfeito de beneficência: dedicar parte do tempo é devido; quanto, é escolha.'), ('prioritarismo', 'Prioritarismo', 'As horas valem mais onde quem é ajudado está pior.')],
 licoes=['quanto-a-moral-pode-exigir', 'pobreza-e-etica-global', 'um-cenario-melhor-ou-o-melhor', 'fraqueza-de-vontade'],
 fx=[('80,000 Hours', 'https://80000hours.org/'), ('Doing Good Better', 'https://www.google.com/search?tbm=bks&q=MacAskill+Doing+Good+Better'), ('Moral Saints', 'https://doi.org/10.2307/2026228')]),

dict(s='doacao-eficaz', n='Doar para as causas mais eficazes?', t=CO, r='Uma doação pode salvar uma vida ou pagar um folheto. O altruísmo eficaz diz que a diferença obriga. Os críticos dizem que a planilha esconde coisas.',
 v='Organizações diferem em centenas de vezes no bem que fazem por real: redes contra malária e vermífugos salvam vidas por poucos milhares de dólares; outras causas gastam o mesmo com efeito pequeno ou nenhum. O altruísmo eficaz propõe doar onde a evidência mostra mais impacto. A pergunta é se isso é um dever, uma boa ideia ou um erro de perspectiva.',
 lados=[('A favor', ['Se doar é bom porque ajuda, doar onde ajuda mais é melhor pela mesma razão; preferir a causa que emociona à que salva é um viés, não uma virtude.', 'Avaliadores independentes (GiveWell, Animal Charity Evaluators) medem resultados; a informação existe, e ignorá-la tem custo em vidas.', 'A diferença de eficácia é enorme: escolher bem multiplica o bem da mesma quantia por dez ou por cem.', 'Causas negligenciadas (pobreza extrema, animais de criação, riscos futuros) recebem pouco porque não comovem, e é onde o dinheiro faz mais.']),
        ('Críticas', ['Crítica institucional: a doação alivia sintomas e deixa intactas as estruturas (comércio, dívida, política) que produzem a pobreza; pode até reduzir a pressão por mudá-las.', 'Mensurabilidade: o que se mede com facilidade (redes, vermífugos) ganha; o que importa e é difícil de medir (instituições, movimentos, arte) perde.', 'Comunidade: dar à própria comunidade sustenta laços e reciprocidade que a doação distante não cria; há um valor nisso que a planilha não vê.', 'Paternalismo e poder: doadores ricos decidindo o que os pobres recebem; transferências diretas de dinheiro são uma resposta a isso.', 'Risco de deformação: o movimento se aproximou de riscos especulativos e de financiadores controversos, o que a crítica usa contra a ideia inteira.'])],
 c=['A crítica institucional é forte sobre onde colocar a maior parte do esforço político, e fraca como razão para não salvar quem morre agora: as duas coisas não competem.', 'Dar à própria comunidade e dar ao mais eficaz não se excluem; a questão é a proporção, e a maioria dá quase nada a nenhum dos dois.', 'A ideia central (olhar o resultado antes de doar) sobrevive às críticas ao movimento que a popularizou.'],
 p=('parcial', 'O peso está com a ideia central: se a doação vale pelo bem que faz, a diferença de eficácia entre causas obriga a olhar os resultados, e a evidência mostra que algumas salvam vidas por muito pouco. As críticas acertam em dois pontos: a mudança estrutural precisa de mais do que doação, e a mensurabilidade enviesa a escolha. Nenhuma delas justifica doar mal ou não doar. A posição mais defendida é doar a maior parte onde a evidência é forte, e manter espaço para a comunidade e para o que não se mede.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Doe onde o bem por real é maior; a emoção da causa não entra na conta.'), ('prioritarismo', 'Prioritarismo', 'Quem está pior tem prioridade, e está quase sempre longe e sem rosto.'), ('etica-do-cuidado', 'Cuidado', 'Começa perto, e não termina perto; a comunidade importa, e a planilha não a vê.'), ('etica-das-virtudes', 'Virtudes', 'Generosidade com sabedoria prática: dar bem é parte da virtude.'), ('deontologia-de-direitos', 'Direitos (Pogge)', 'Não é caridade, é reparação; e a reparação exige mudar as regras, não só doar.')],
 licoes=['pobreza-e-etica-global', 'vieses-morais', 'teoria-da-decisao-e-etica', 'quanto-a-moral-pode-exigir'],
 fx=[('GiveWell', 'https://www.givewell.org/'), ('Animal Charity Evaluators', 'https://animalcharityevaluators.org/'), ('Effective altruism (Wikipédia)', WE + 'Effective_altruism'), ('The Life You Can Save', 'https://www.thelifeyoucansave.org/')]),

dict(s='compensacao-moral', n='Compensação moral: doar compensa causar dano?', t=CO, r='Comer carne e doar para proteger animais, poluir e comprar créditos de carbono: o saldo pode ser “excelente”. O que a aritmética esconde.',
 v='Uma pessoa come produtos de animais criados industrialmente e doa, todo ano, para organizações eficazes de defesa animal; calcula que sua doação poupa mais animais do que seu consumo prejudica, e conclui que seu impacto é excelente. O mesmo raciocínio aparece com créditos de carbono. A pergunta é se causar um dano pode ser compensado por evitar outro, e o que a conta deixa de fora.',
 lados=[('O que a compensação acerta', ['Doar é bom, e doar bem é melhor; quem doa muito faz mais bem do que quem não doa, independentemente do que come. A doação não deve ser desprezada porque a pessoa não é perfeita.', 'Em uma conta puramente agregada, o saldo líquido existe: se a doação poupa mil animais e o consumo prejudica cem, o mundo tem menos sofrimento do que teria sem essa pessoa.', 'Exigir pureza afasta: quem não consegue mudar o prato pode começar pela doação, e isso já é progresso. Veja um cenário melhor ou o melhor cenário.']),
        ('O que a compensação esconde', ['As vítimas não são intercambiáveis: o frango que você come não é poupado pelo frango que sua doação salva. Compensação funciona para somas; não funciona para quem sofreu. É como pagar a fiança de um estranho para ter licença de bater em outro.', 'Causar e prevenir não são simétricos para a maioria das teorias: há uma diferença entre não causar dano e compensá-lo depois, e ela é o centro da deontologia e aparece até no consequencialismo de regras.', 'O saldo “excelente” compara com a pessoa que nem doa nem muda; o melhor cenário disponível, para quem pode, é doar e não causar o dano. A compensação troca o melhor pelo melhor-que-nada e chama isso de ótimo.', 'Licença moral: a psicologia mostra que fazer algo bom aumenta a tolerância a fazer algo ruim em seguida; a compensação é o mecanismo institucionalizado.', 'Honestidade da conta: a doação costuma ser calculada com otimismo e o consumo, com desconto; e o argumento raramente é usado por quem doa muito, e sim por quem quer não mudar.'])],
 c=['Há uma diferença entre compensação como estratégia de transição (“ainda não consigo mudar tudo, então doo enquanto mudo”) e como licença permanente (“doo, logo posso”). A primeira é honesta; a segunda, não.', 'Créditos de carbono têm o problema adicional de muitas vezes não compensarem de fato o que prometem.', 'Para causas em que o dano é difuso e o agente não pode evitá-lo por completo (emissões para viver), compensar é o melhor disponível; para o prato, há alternativa direta, e isso muda o veredito.'],
 p=('parcial', 'O peso está contra a compensação como licença: as vítimas não se trocam, causar e prevenir não são simétricos, e o “saldo excelente” compara com a pior alternativa em vez de com a melhor disponível, que é doar e não causar o dano. O que a compensação acerta é que doar é bom e que a pureza não deve ser exigida: como estratégia de transição honesta, ela vale; como argumento para não mudar o que se pode mudar, ela é uma racionalização, e a psicologia da licença moral explica por que convence tanto.'),
 teorias=[('consequencialismo-de-ato', 'Consequencialismo de ato', 'O saldo agregado conta, e o da pessoa é positivo; mas a melhor opção disponível é doar e não causar o dano, e a teoria exige a melhor.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “compense o dano que causa” produz menos bem do que “não cause dano evitável e doe”; e corrói a norma de não causar.'), ('deontologia-de-direitos', 'Direitos', 'O animal que você come tem um direito violado que nenhuma doação restaura; compensação não é reparação à vítima.'), ('etica-das-virtudes', 'Virtudes', 'A pessoa íntegra não negocia consigo mesma licenças para o que sabe que é errado; a generosidade não paga a crueldade.'), ('sencientismo', 'Sencientismo', 'Cada ser conta por si; a conta que o troca por outro perdeu o ponto.')],
 licoes=['etica-animal-na-pratica', 'fazer-e-deixar-acontecer', 'um-cenario-melhor-ou-o-melhor', 'fraqueza-de-vontade', 'vieses-morais'],
 fx=[('Moral licensing (Wikipédia)', WE + 'Self-licensing'), ('Carbon offset (Wikipédia)', WE + 'Carbon_offset'), ('Animal Charity Evaluators', 'https://animalcharityevaluators.org/')]),
]
assert len({d['s'] for d in DEBATES9}) == len(DEBATES9)
